 void BuildAnchoredControls(FlowLayoutPanel parent){anchoredControls.FlowDirection=FlowDirection.TopDown;anchoredControls.WrapContents=false;anchoredControls.AutoSize=true;anchoredControls.Width=250;anchoredControls.Margin=new Padding(0);parent.Controls.Add(anchoredControls);extraControls.Add(anchoredControls);AddLabel(anchoredControls,"V15.6: gộp cue thành câu đọc, giữ tổng thời lượng và mốc từng chặng. Tích Khóa cuối chặng trong bảng tại điểm neo cần giữ.",false);anchoredControls.Controls.Add(Btn("Xem chặng / báo cáo",(s,e)=>ShowAnchoredReport()));anchoredSrt.Text="Tạo thêm SRT theo WAV";anchoredSrt.AutoSize=true;anchoredSrt.MaximumSize=new Size(250,0);anchoredControls.Controls.Add(anchoredSrt);AddLabel(anchoredControls,"Mặc định chỉ WAV. SRT theo từ cần bộ phụ đề đã cài; lời/mốc SRT nguồn giữ nguyên.",false);anchoredSrt.CheckedChanged+=(s,e)=>{if(stateLoaded&&!restoring)SaveSession();};mode.SelectedIndexChanged+=(s,e)=>{lastAnchorReport=null;RefreshAnchorControls();RefreshSummary();};grid.CurrentCellDirtyStateChanged+=(s,e)=>{if(!anchorGridLoading&&grid.CurrentCell!=null&&grid.CurrentCell.ColumnIndex==6&&grid.IsCurrentCellDirty)grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};grid.CellValueChanged+=(s,e)=>{if(!anchorGridLoading&&e.RowIndex>=0&&e.ColumnIndex==6&&e.RowIndex<cues.Count)try{ReadGrid();RefreshSummary();}catch(Exception ex){status.Text=ex.Message;}};RefreshAnchorControls();}
