 void ConfigureAnchored(RenderOptions o){o.Anchored=AnchoredMode;o.AnchorChanged=r=>lastAnchorReport=r;if(anchoredSrt.Checked&&VietnameseSelected){o.AnchorAlignment=(audio,units)=>{throw new Exception("WAV tiếng Việt đã giữ. Căn từng từ tiếng Việt chưa được tích hợp; bỏ chọn Tạo thêm SRT theo WAV.");};}else if(anchoredSrt.Checked){string device=SubtitleDeviceKey;o.AnchorAlignment=(audio,units)=>AlignAnchoredAudio(audio,units,device);}}
 SubtitleDocument AlignAnchoredAudio(string audio,List<AnchorUnit> units,string device){RequireSubtitleRuntime();if(!File.Exists(Path.Combine(SubtitleHome,"models","alignment","wav2vec2_fairseq_base_ls960_asr_ls960.pth")))throw new Exception("Cần cài bộ phụ đề ở tab MP4/MP3 → SRT để căn từng từ. WAV vẫn được giữ.");string work=Path.Combine(Path.GetTempPath(),"V15_align_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);string draft=Path.Combine(work,"units.xml"),result=Path.Combine(work,"aligned.xml");try{new XElement("units",units.Select(u=>new XElement("unit",new XAttribute("stage",u.Stage),new XAttribute("start",u.Start),new XAttribute("end",u.End),new XAttribute("stageStart",u.StageStart),new XAttribute("stageEnd",u.StageEnd),u.Text))).Save(draft);if(active!=null&&active.Cancelled)throw new OperationCanceledException();subtitleProcess=new SubtitleProcess();subtitleProcess.Run(SubtitlePython,SubtitleScript("voice_alignment.py"),"--home "+KokoroEngine.Q(SubtitleHome)+" --input "+KokoroEngine.Q(audio)+" --draft "+KokoroEngine.Q(draft)+" --output "+KokoroEngine.Q(result)+" --ffmpeg "+KokoroEngine.Q(Tempo.Executable(root))+" --device "+device,SubtitleNotify);return SubtitleDocument.Load(result);}finally{if(subtitleProcess!=null)subtitleProcess.Dispose();subtitleProcess=null;try{Directory.Delete(work,true);}catch{}}}
