 async Task MeasureAnchored(){string dir=Path.Combine(Path.GetTempPath(),"V15_measure_"+Guid.NewGuid().ToString("N"));try{ReadGrid();Directory.CreateDirectory(dir);var o=Options();o.ReportContext=null;o.NormalizeLoudness=false;o.AnchorAlignment=null;var copy=cues.Select(c=>new Cue{Id=c.Id,Text=c.Text,Speaker=c.Speaker,Start=c.Start,End=c.End,AnchorAfter=c.AnchorAfter}).ToList();active=RunEngine(copy);active.CheckFiles();SetBusy(true);var engine=active;string failure="";try{await Task.Run(()=>Renderer.Render(copy,engine,o,Path.Combine(dir,"measure.wav"),(p,m)=>{if(!IsDisposed)BeginInvoke((Action)(()=>{progress.Value=p;status.Text=m;}));}));}catch(OperationCanceledException){throw;}catch(Exception e){if(o.AnchorResult==null||o.AnchorResult.Stages.Count==0)throw;failure=e.Message;}SetBusy(false);if(o.AnchorResult!=null){o.AnchorResult.Complete=false;o.AnchorResult.Wav="";TextReport("ĐO THỬ · chưa xuất WAV bên cạnh nguồn. Âm thanh đọc đã được lưu đệm để dùng lại khi tạo voice.\r\n"+o.AnchorResult.Describe()+(failure.Length>0?"\r\nCó chặng cần sửa trước khi xuất.":""),"Đo giọng theo chặng V15.6");}status.Text="Đã đo giọng theo chặng.";}catch(OperationCanceledException){status.Text="Đã dừng đo giọng.";}catch(Exception e){Error(e);}finally{if(active!=null)active.Dispose();active=null;SetBusy(false);try{Directory.Delete(dir,true);}catch{}}}
 void SaveSourceAnchors(){if(proseInput||String.IsNullOrEmpty(sourcePath)||!File.Exists(sourcePath)||cues.Count==0)return;try{var x=new XElement("sourceAnchors",new XAttribute("source",sourcePath),new XAttribute("hash",StateFiles.Hash(sourcePath)),cues.Select(c=>new XElement("cue",new XAttribute("start",c.Start),new XAttribute("end",c.End),new XAttribute("anchor",c.AnchorAfter?1:0),c.Text)));StateFiles.Write(Path.Combine(stateDir,"source_anchors.xml"),x);}catch(Exception e){status.Text="Chưa lưu được neo chặng: "+e.Message;}}
 void RestoreSourceAnchors(){if(proseInput||String.IsNullOrEmpty(sourcePath))return;try{var x=StateFiles.Read(Path.Combine(stateDir,"source_anchors.xml"));if(x==null||StateFiles.S(x,"source")!=sourcePath||StateFiles.S(x,"hash")!=StateFiles.Hash(sourcePath))return;var rows=x.Elements("cue").ToList();if(rows.Count!=cues.Count)return;for(int i=0;i<rows.Count;i++)if(rows[i].Value!=cues[i].Text||Math.Abs(StateFiles.D(rows[i],"start")-cues[i].Start)>.0001||Math.Abs(StateFiles.D(rows[i],"end")-cues[i].End)>.0001)return;for(int i=0;i<rows.Count;i++)cues[i].AnchorAfter=StateFiles.I(rows[i],"anchor")==1;}catch{}}

